// Median prices by parish. PROVISIONAL: shape only, until the INE series are generated by
// scripts/build-precos.py. Do not ship these numbers.

type Series = [year: number, value: number][];

const LISBOA_SALE: Series = [
  [2015, 2000], [2016, 2100], [2017, 2500], [2018, 2950], [2019, 3250], [2020, 3400],
  [2021, 3550], [2022, 3950], [2023, 4150], [2024, 4450], [2025, 4875],
];
const LISBOA_RENT: Series = [
  [2015, 9.5], [2016, 10.5], [2017, 11.5], [2018, 12.5], [2019, 13.2], [2020, 12.8],
  [2021, 12.6], [2022, 14.2], [2023, 15.6], [2024, 16.6], [2025, 17.4],
];
const REL: Record<string, number> = {
  '110601': 0.78, '110602': 0.95, '110607': 0.8, '110608': 0.8, '110610': 0.9, '110611': 0.78,
  '110618': 0.88, '110621': 0.66, '110633': 0.74, '110639': 0.86, '110654': 0.98, '110655': 0.98,
  '110656': 0.92, '110657': 1.08, '110658': 1.02, '110659': 1.13, '110660': 1.13, '110661': 1.1,
  '110662': 1.2, '110663': 0.85, '110664': 0.6, '110665': 1.06, '110666': 1.24, '110667': 0.92,
};

export const SCENARIO_GROWTH = 0.04;
export const LAST_DATA_YEAR = 2025;

function interp(s: Series, y: number): number {
  if (y <= s[0][0]) return s[0][1];
  for (let i = 1; i < s.length; i++) {
    if (y <= s[i][0]) {
      const [a, va] = s[i - 1], [b, vb] = s[i];
      return va + ((vb - va) * (y - a)) / (b - a);
    }
  }
  const [last, v] = s[s.length - 1];
  return v * Math.pow(1 + SCENARIO_GROWTH, y - last);
}

/** Median sale price, €/m², at a fractional year. */
export const priceM2 = (code: string, year: number) => interp(LISBOA_SALE, year) * (REL[code] ?? 1);
/** Median rent of new leases, €/m²/month, at a fractional year. */
export const rentM2 = (code: string, year: number) => interp(LISBOA_RENT, year) * (0.6 + 0.4 * (REL[code] ?? 1));
export const lisboaPriceM2 = (year: number) => interp(LISBOA_SALE, year);

export const PRICE_SOURCES: { title: string; url: string; period: string }[] = [];
